int main(int n,char**a){assert(n==2&&pllato_open(a[1])<128);assert(!pllato_preserve_source(a[1]));unsigned count=0;for(unsigned i=0;i<drawing.num_objects;i++){Dwg_Object*o=drawing.object+i;if(!source_body_type(o))continue;unsigned bits;unsigned char*p=source_body_backup(o,&bits);if(!p||!bits){fprintf(stderr,"FAIL %llX type=%u size=%u common=%u bits=%u handles=%u rest=%u\n",(unsigned long long)o->handle.value,o->type,o->size,o->common_size,o->bitsize,o->handlestream_size,o->num_unknown_rest);return 2;}free(p);PP_Record*r=pp_source.records+i;PP_Section*s=pp_find(pp_source.sections,pp_source.nsections,"AcDb:AcDbObjects");unsigned char old=s->bytes[r->address];s->bytes[r->address]^=1;assert(!source_body_backup(o,&bits));s->bytes[r->address]=old;count++;}assert(count);printf("PASS %u bounded source bodies, CRC corruption rejected\n",count);}
